import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type AppleWatchChargingProps = Record<string, any>;

const AppleWatchCharging: React.FC<AppleWatchChargingProps> = ({
  backgroundColor = "#000000",
  transparentBackground = false,
  primaryColor = "#32D74B", // Classic Apple charging green
  trackColor = "#1C1C1E",   // Dark grey track
  iconColor = "#ffffff",
  batteryLevel = 68,
  ringRadius = 180,
  strokeWidth = 24,
  durationInSeconds = 5,
  showPercentage = true,
}) => {
  // Load standard sans-serif font
  useFontLoader(["Inter"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // 1. Setup Background
  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // 2. Constants for SVG Circle
  const radius = ringRadius;
  const circumference = 2 * Math.PI * radius;
  const center = { x: width / 2, y: height / 2 };

  // 3. Animation: Entrance Spring (Scale & Opacity)
  // The UI pops in quickly like the real watch
  const entranceScale = spring({
    frame,
    fps,
    config: {
      damping: 12,
      stiffness: 100,
      mass: 0.5,
    },
  });

  // 4. Animation: Charging Progress
  // Interpolate from 0 to the target battery level smoothly for the ring
  const progress = interpolate(
    frame,
    [0, fps * (durationInSeconds * 0.6)], // Animate over 60% of duration
    [0, batteryLevel],
    {
      extrapolateRight: "clamp",
    }
  );

  // Convert progress (0-100) to stroke dash offset
  const strokeDashoffset = circumference - (progress / 100) * circumference;

  // Combine entrance for the ring glow container
  const combinedScale = entranceScale; 
  
  // Shadow/Glow effect matching the primary color
  const glowStyle = {
    filter: `drop-shadow(0px 0px 10px ${primaryColor}80)`, // 50% opacity hex
  };

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: "Inter",
        justifyContent: "center",
        alignItems: "center",
      }}
    >
      <div
        style={{
          position: "relative",
          width: radius * 2 + strokeWidth * 2,
          height: radius * 2 + strokeWidth * 2,
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          transform: `scale(${combinedScale})`,
        }}
      >
        <svg
          width={radius * 2 + strokeWidth * 2}
          height={radius * 2 + strokeWidth * 2}
          viewBox={`0 0 ${radius * 2 + strokeWidth * 2} ${radius * 2 + strokeWidth * 2}`}
          style={{
            transform: "rotate(-90deg)", // Rotate so start is at 12 o'clock
            overflow: "visible",
          }}
        >
          {/* Background Track */}
          <circle
            cx="50%"
            cy="50%"
            r={radius}
            stroke={trackColor}
            strokeWidth={strokeWidth}
            fill="none"
            strokeLinecap="round"
            style={{ opacity: 0.5 }}
          />

          {/* Active Progress Ring */}
          <circle
            cx="50%"
            cy="50%"
            r={radius}
            stroke={primaryColor}
            strokeWidth={strokeWidth}
            fill="none"
            strokeLinecap="round"
            strokeDasharray={circumference}
            strokeDashoffset={strokeDashoffset}
            style={{
              ...glowStyle,
              transition: "none", // Explicitly disable CSS transition
            }}
          />
        </svg>

        {/* Center Content: Bolt & Text */}
        <div
          style={{
            position: "absolute",
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
            justifyContent: "center",
            color: iconColor,
          }}
        >
          {/* Replaced Lucide Zap with inline SVG to avoid dependency issues */}
          <svg
            width={radius * 0.6}
            height={radius * 0.6}
            viewBox="0 0 24 24"
            fill={iconColor}
            stroke="none"
            strokeWidth="0"
            strokeLinecap="round"
            strokeLinejoin="round"
            style={{
              marginBottom: showPercentage ? radius * 0.1 : 0,
              filter: `drop-shadow(0px 0px 15px ${primaryColor}40)`,
            }}
          >
            <polygon points="13 2 3 14 12 14 11 22 21 10 12 10 13 2" />
          </svg>
          
          {showPercentage && (
            <span
              style={{
                fontSize: radius * 0.35,
                fontWeight: 600,
                lineHeight: 1,
                textShadow: `0px 0px 20px ${primaryColor}60`,
                marginTop: 10
              }}
            >
              {/* Static percentage as requested */}
              {batteryLevel}%
            </span>
          )}
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default AppleWatchCharging;